SELECT 'bbbbbbbb-bbbb-bbbb-bbbb-000000000002', cm.id, '1.0.0', 'APPROVED', 'ACTIVE',
       '{"blocks":[{"type":"paragraph","text":"Schedule 2 - Conditions Precedent forms an integral part of this Facility Offer Letter and shall be read together with the operative clauses. Capitalised terms used in this Schedule have the meanings given in Clause 1 (Definitions and Interpretation) unless the context otherwise requires."},{"type":"paragraph","text":"Part 1 - Corporate documents. A certified copy of the constitutional documents of each Obligor; a certified copy of board resolutions approving the Finance Documents and authorising specified signatories; a specimen signature list; and a certificate of an authorised signatory confirming that borrowing or guaranteeing the Total Commitments would not cause any borrowing, guaranteeing or similar limit binding on that Obligor to be exceeded."},{"type":"paragraph","text":"Part 2 - Finance Documents. Executed counterparts of this letter, each Fee Letter, each Security Document required on or before first Utilisation, any Accession Letter for an Additional Guarantor, and evidence that all conditions to the effectiveness of each such document (other than conditions expressed to be satisfied on Utilisation) have been satisfied or waived by the Agent."},{"type":"paragraph","text":"Part 3 - Legal opinions. A legal opinion of English counsel to the Agent as to English law enforceability; a legal opinion of Cayman Islands counsel as to capacity and due execution of the Borrower and Guarantor; and, if any Security Document is governed by another law, a capacity and enforceability opinion from counsel acceptable to the Agent in that jurisdiction."},{"type":"paragraph","text":"Part 4 - KYC, sanctions and AML. Completion of all know-your-customer, anti-money-laundering and sanctions screening procedures reasonably required by each Finance Party in relation to each Obligor and each person purporting to act on behalf of an Obligor, including delivery of beneficial ownership information and evidence that no Obligor is a Sanctioned Person."},{"type":"paragraph","text":"Part 5 - Financial and commercial evidence. The Group''s latest audited consolidated financial statements; the most recent quarterly management accounts; a structure chart; evidence of insurance covering material assets with the Security Agent''s interest noted where required; and a funds flow statement for the first Utilisation."},{"type":"paragraph","text":"Part 6 - Conditions subsequent. Within 30 days of the Signing Date (or such later date as the Agent may agree), the Borrower shall deliver evidence of registration or perfection of each Security Document required to be registered, and any other condition subsequent listed in the closing checklist agreed with the Agent."},{"type":"paragraph","text":"Part 7 - Repeating conditions for each Utilisation. On the date of each Utilisation Request and each Utilisation Date: (a) no Default is continuing or would result from the proposed Utilisation; (b) the Repeating Representations are true in all material respects; (c) the Utilisation is within the Availability Period and does not exceed available Commitments; and (d) the Agent has received a duly completed Utilisation Request."},{"type":"paragraph","text":"The Agent shall notify the Borrower and the Lenders promptly upon satisfaction or waiver of the conditions in Parts 1 to 5."},{"type":"paragraph","text":"Any waiver of a condition precedent may be given by the Agent acting on the instructions of the Majority Lenders, or by all Lenders where the Finance Documents so require."},{"type":"paragraph","text":"Documents delivered under this Schedule shall be in English or accompanied by a certified English translation."},{"type":"paragraph","text":"Electronic copies are acceptable if originally signed wet-ink or e-signed counterparts follow within five Business Days where a Finance Party so requires."},{"type":"paragraph","text":"Failure to satisfy a condition subsequent by its long-stop date shall constitute an Event of Default unless remedied or waived in accordance with Clause 22 (Events of Default)."},{"type":"paragraph","text":"The Borrower shall pay all reasonable legal fees of the Agent''s counsel incurred in reviewing Conditions Precedent deliveries, as set out in the Fee Letter."}]}',
       'Wholesale FOL LMA-style import', '10000003', '10000007'
FROM content_module cm
WHERE cm.module_code = 'MOD-FOL-SCH-02' AND cm.deleted_at IS NULL
  AND NOT EXISTS (
      SELECT 1 FROM content_module_version v
      WHERE v.module_id = cm.id AND v.semantic_version = '1.0.0'
  );

