INSERT INTO content_module_version (
    id, module_id, semantic_version, review_state, lifecycle_state,
    content_structure_json, change_description, created_by, updated_by
)
SELECT 'bbbbbbbb-bbbb-bbbb-bbbb-000000000004', cm.id, '1.0.0', 'APPROVED', 'ACTIVE',
       '{"blocks":[{"type":"paragraph","text":"Schedule 4 - Form of Utilisation Request forms an integral part of this Facility Offer Letter and shall be read together with the operative clauses. Capitalised terms used in this Schedule have the meanings given in Clause 1 (Definitions and Interpretation) unless the context otherwise requires."},{"type":"paragraph","text":"Part 1 - Form. Each Utilisation Request shall be substantially in the form of this Schedule, addressed to the Agent, signed by an authorised signatory of the Borrower, and delivered not later than 10:00 a.m. (London time) three Business Days before the proposed Utilisation Date (or such shorter period as the Agent may agree)."},{"type":"paragraph","text":"Part 2 - Mandatory content. The Utilisation Request shall specify: (a) the proposed Utilisation Date; (b) the currency and amount of the proposed Loan; (c) the Interest Period; (d) the account to which funds are to be credited; and (e) confirmation that each condition in Clause 4 (Conditions of Utilisation) is satisfied on the date of the Utilisation Request."},{"type":"paragraph","text":"Part 3 - Minimum amounts. Unless the Agent otherwise agrees, each Loan shall be in a minimum amount of USD 5,000,000 (or its equivalent) and an integral multiple of USD 1,000,000 (or its equivalent)."},{"type":"paragraph","text":"Part 4 - Irrevocability. A Utilisation Request is irrevocable once delivered, except with the prior written consent of the Agent (acting on the instructions of the Majority Lenders where a change would alter Commitments or pricing)."},{"type":"paragraph","text":"Part 5 - Agent notification. Promptly upon receipt of a duly completed Utilisation Request, the Agent shall notify each Lender of the amount of its participation and the account details for funding."},{"type":"paragraph","text":"Part 6 - Transfer Certificate cross-reference. Where a Lender has transferred part of its Commitment, Utilisation Requests shall be processed by reference to Commitments recorded in the Agent''s register, which prevails over outdated matrices in Schedule 1 for operational purposes."},{"type":"paragraph","text":"If a Utilisation Request is defective, the Agent shall notify the Borrower of the defect as soon as practicable and the Borrower may submit a corrected request."},{"type":"paragraph","text":"Currency conversions for multicurrency utilisations shall use the Agent''s Spot Rate of Exchange as defined in Clause 1."},{"type":"paragraph","text":"The Borrower represents, on delivery of each Utilisation Request, that the proceeds will be applied solely for a Purpose permitted under Clause 3 (Purpose)."},{"type":"paragraph","text":"Same-day utilisations are not available unless all Lenders consent in writing."},{"type":"paragraph","text":"A Utilisation Request may not be delivered during a market disruption period notified under Clause 10 (Changes to the Calculation of Interest) without Agent guidance on rate setting."},{"type":"paragraph","text":"Electronic delivery by encrypted email to the Agent''s published utilisation desk address constitutes delivery for the purposes of this Schedule."}]}',
       'Wholesale FOL LMA-style import', '10000003', '10000007'
FROM content_module cm
WHERE cm.module_code = 'MOD-FOL-SCH-04' AND cm.deleted_at IS NULL
  AND NOT EXISTS (
      SELECT 1 FROM content_module_version v
      WHERE v.module_id = cm.id AND v.semantic_version = '1.0.0'
  );

