-- MOD-FOL-SCH-05 -> FOL_SCHEDULE_05_FEES (13 paragraphs)
INSERT INTO content_module (id, module_code, group_code, name, description, shared_group_codes_json, created_by, updated_by)
SELECT 'aaaaaaaa-aaaa-aaaa-aaaa-000000000005', 'MOD-FOL-SCH-05', 'CORP', 'Schedule 5 - Fees', 'Wholesale FOL LMA-style standard clause', '[]', '10000003', '10000003'
WHERE NOT EXISTS (
    SELECT 1 FROM content_module WHERE module_code = 'MOD-FOL-SCH-05' AND deleted_at IS NULL
