INSERT INTO content_module_version (
    id, module_id, semantic_version, review_state, lifecycle_state,
    content_structure_json, change_description, created_by, updated_by
)
SELECT 'bbbbbbbb-bbbb-bbbb-bbbb-000000000005', cm.id, '1.0.0', 'APPROVED', 'ACTIVE',
       '{"blocks":[{"type":"paragraph","text":"Schedule 5 - Fees forms an integral part of this Facility Offer Letter and shall be read together with the operative clauses. Capitalised terms used in this Schedule have the meanings given in Clause 1 (Definitions and Interpretation) unless the context otherwise requires."},{"type":"paragraph","text":"Part 1 - Arrangement fee. The Borrower shall pay to the Arranger an arrangement fee in the amount and on the dates set out in the Fee Letter between the Arranger and the Borrower dated on or about the Signing Date."},{"type":"paragraph","text":"Part 2 - Commitment fee. The Borrower shall pay to the Agent (for the account of each Lender) a commitment fee computed at the rate specified in Schedule 1 (Facility Particulars) on that Lender''s Available Commitment, accruing from the Signing Date and payable quarterly in arrear and on the date the relevant Commitment is cancelled in full."},{"type":"paragraph","text":"Part 3 - Agency fee. The Borrower shall pay to the Agent an agency fee in the amount and at the times agreed in the Agency Fee Letter. The fee is payable for the Agent''s own account and is non-refundable."},{"type":"paragraph","text":"Part 4 - Security agency fee. Where a Security Agent is appointed, the Borrower shall pay the security agency fee set out in the relevant Fee Letter, together with reasonable out-of-pocket expenses properly incurred in connection with the Security Documents."},{"type":"paragraph","text":"Part 5 - Utilisation and front-end fees. Any utilisation fee or front-end fee agreed in a Fee Letter shall be payable on the first Utilisation Date (or such other date specified in that Fee Letter) and shall not be refundable whether or not the Facility is utilised in full."},{"type":"paragraph","text":"Part 6 - Fee Letter prevalence. If there is any conflict between this Schedule and a Fee Letter, the Fee Letter prevails in respect of the quantum and timing of the relevant fee, without prejudice to the Borrower''s payment obligations under Clause 11 (Fees)."},{"type":"paragraph","text":"Fees are exclusive of any VAT, which shall be paid in addition if chargeable."},{"type":"paragraph","text":"The Agent may deduct unpaid fees from amounts otherwise payable to the Borrower under the Finance Documents."},{"type":"paragraph","text":"No fee sharing with the Borrower or any Obligor is permitted except as disclosed in a Fee Letter."},{"type":"paragraph","text":"Amendment and waiver fees, if any, shall be agreed at the time of the relevant consent request."},{"type":"paragraph","text":"Breakage and funding indemnities under Clause 7 and Clause 14 are in addition to the fees in this Schedule."},{"type":"paragraph","text":"Evidence of fee payment may be required as a condition subsequent under Schedule 2 (Conditions Precedent)."}]}',
       'Wholesale FOL LMA-style import', '10000003', '10000007'
FROM content_module cm
WHERE cm.module_code = 'MOD-FOL-SCH-05' AND cm.deleted_at IS NULL
  AND NOT EXISTS (
      SELECT 1 FROM content_module_version v
      WHERE v.module_id = cm.id AND v.semantic_version = '1.0.0'
  );

