-- MOD-FOL-SCH-06 -> FOL_SCHEDULE_06_SECURITY_PRINCIPLES (14 paragraphs)
INSERT INTO content_module (id, module_code, group_code, name, description, shared_group_codes_json, created_by, updated_by)
SELECT 'aaaaaaaa-aaaa-aaaa-aaaa-000000000006', 'MOD-FOL-SCH-06', 'CORP', 'Schedule 6 - Security Principles', 'Wholesale FOL LMA-style standard clause', '[]', '10000003', '10000003'
WHERE NOT EXISTS (
    SELECT 1 FROM content_module WHERE module_code = 'MOD-FOL-SCH-06' AND deleted_at IS NULL
);

INSERT INTO content_module_version (
    id, module_id, semantic_version, review_state, lifecycle_state,
    content_structure_json, change_description, created_by, updated_by
)
SELECT 'bbbbbbbb-bbbb-bbbb-bbbb-000000000006', cm.id, '1.0.0', 'APPROVED', 'ACTIVE',
       '{"blocks":[{"type":"paragraph","text":"Schedule 6 - Security Principles forms an integral part of this Facility Offer Letter and shall be read together with the operative clauses. Capitalised terms used in this Schedule have the meanings given in Clause 1 (Definitions and Interpretation) unless the context otherwise requires."},{"type":"paragraph","text":"Security over shares in the Borrower, account charges, receivables assignments and intercreditor arrangements form the agreed Transaction Security package and shall be documented in the Security Documents listed with the Agent."},{"type":"paragraph","text":"Part 1 - Transaction Security. The Obligors shall grant Transaction Security in favour of the Security Agent (as trustee or agent for the Finance Parties) comprising: (a) a charge over shares in the Borrower; (b) fixed and floating charges or equivalent over material bank accounts; (c) assignments of material receivables; and (d) such other Security as the Majority Lenders reasonably require to implement the agreed security package."},{"type":"paragraph","text":"Part 2 - Perfection. Each Obligor shall execute all documents and do all acts reasonably required to perfect and protect the Transaction Security, including registrations, notices to account banks and delivery of share certificates and blank stock transfer forms."},{"type":"paragraph","text":"Part 3 - Accession. An Additional Guarantor shall accede by delivering an Accession Letter substantially in the form agreed with the Agent, together with the corporate documents and legal opinions listed in Schedule 2 (Conditions Precedent) as applicable to that Additional Guarantor."},{"type":"paragraph","text":"Part 4 - Intercreditor. If any Intercreditor Agreement is entered into, the ranking, enforcement standstill and turnover provisions of that agreement shall regulate the relative rights of the Finance Parties and other creditors party to it."},{"type":"paragraph","text":"Part 5 - Release. Subject to the Finance Documents, Transaction Security shall be released when all amounts outstanding under the Finance Documents have been irrevocably paid and discharged in full and the Commitments have been cancelled."},{"type":"paragraph","text":"Part 6 - Further assurance. Each Obligor shall, at its own expense, promptly execute any further document and take any further action that the Security Agent may reasonably require to give effect to the security principles in this Schedule."},{"type":"paragraph","text":"Security Documents shall be governed by the law most appropriate for the asset location, as advised by counsel to the Agent."},{"type":"paragraph","text":"Account charges shall require blocked or controlled account mechanics only to the extent specified in the agreed term sheet."},{"type":"paragraph","text":"Insurance proceeds in respect of secured assets shall be applied in accordance with Clause 7 (Prepayment and Cancellation) unless reinvested as Permitted Security exceptions allow."},{"type":"paragraph","text":"The Security Agent may appoint delegates and co-agents in accordance with Clause 24 (The Agent and the Arrangers)."},{"type":"paragraph","text":"Whitewash, financial assistance and corporate benefit analysis shall be completed before any English or Cayman share security is taken."},{"type":"paragraph","text":"No Obligor shall create Permitted Security except as expressly allowed under Clause 21 (General Undertakings)."}]}',
       'Wholesale FOL LMA-style import', '10000003', '10000007'
FROM content_module cm
WHERE cm.module_code = 'MOD-FOL-SCH-06' AND cm.deleted_at IS NULL
  AND NOT EXISTS (
      SELECT 1 FROM content_module_version v
      WHERE v.module_id = cm.id AND v.semantic_version = '1.0.0'
  );

