UPDATE content_module_version v
SET content_structure_json = '{"blocks":[{"type":"paragraph","text":"Clause 27 (Payment Mechanics). This Clause sets out the terms relating to Payment Mechanics in accordance with the LMA recommended form for investment grade syndicated facilities and market practice for wholesale international bank financings documented under English law."},{"type":"paragraph","text":"27.1 Payments to Agent distribution account. The Borrower and each Finance Party acknowledge that the provisions of this sub-clause reflect standard LMA drafting for investment grade borrowers and are subject to facility-specific negotiation recorded in the term sheet and Schedule 1 (Facility Particulars)."},{"type":"paragraph","text":"Without limiting the generality of sub-clause 27.1, each Obligor shall procure that all actions required to give full effect to Payments to Agent distribution account are completed within the timeframes and according to the procedures customary for a syndicated term facility of this nature, including delivery of certificates, opinions and evidence reasonably requested by the Agent acting on the instructions of the Majority Lenders."},{"type":"paragraph","text":"The Agent may, after consultation with the Borrower where practicable, issue guidance or process notes to the Lenders regarding operational matters arising under sub-clause 27.1, provided that such guidance does not amend the legal obligations of the Obligors without a formal amendment to the Finance Documents."},{"type":"paragraph","text":"In negotiating sub-clause 27.1, the Borrower and the Lenders typically consider counsel comments against the LMA recommended form, internal credit policy requirements, and any side letter or term sheet provisions agreed at mandate stage. Any deviation from the LMA baseline is recorded in the execution version of the Finance Documents."},{"type":"paragraph","text":"Operational application: where Payments to Agent distribution account applies to the Facility offered to Pacific Rim Holdings Ltd., the Agent will coordinate with the Borrower and the Security Agent to ensure timelines, document versions and evidence standards match those set out in Schedule 2 (Conditions Precedent) and Meridian Global Banking Corporation wholesale credit operations standards."},{"type":"paragraph","text":"27.2 Currency of account and payment. The Borrower and each Finance Party acknowledge that the provisions of this sub-clause reflect standard LMA drafting for investment grade borrowers and are subject to facility-specific negotiation recorded in the term sheet and Schedule 1 (Facility Particulars)."},{"type":"paragraph","text":"Without limiting the generality of sub-clause 27.2, each Obligor shall procure that all actions required to give full effect to Currency of account and payment are completed within the timeframes and according to the procedures customary for a syndicated term facility of this nature, including delivery of certificates, opinions and evidence reasonably requested by the Agent acting on the instructions of the Majority Lenders."},{"type":"paragraph","text":"The Agent may, after consultation with the Borrower where practicable, issue guidance or process notes to the Lenders regarding operational matters arising under sub-clause 27.2, provided that such guidance does not amend the legal obligations of the Obligors without a formal amendment to the Finance Documents."},{"type":"paragraph","text":"In negotiating sub-clause 27.2, the Borrower and the Lenders typically consider counsel comments against the LMA recommended form, internal credit policy requirements, and any side letter or term sheet provisions agreed at mandate stage. Any deviation from the LMA baseline is recorded in the execution version of the Finance Documents."},{"type":"paragraph","text":"Operational application: where Currency of account and payment applies to the Facility offered to Pacific Rim Holdings Ltd., the Agent will coordinate with the Borrower and the Security Agent to ensure timelines, document versions and evidence standards match those set out in Schedule 2 (Conditions Precedent) and Meridian Global Banking Corporation wholesale credit operations standards."},{"type":"paragraph","text":"27.3 Partial payments and set-off. The Borrower and each Finance Party acknowledge that the provisions of this sub-clause reflect standard LMA drafting for investment grade borrowers and are subject to facility-specific negotiation recorded in the term sheet and Schedule 1 (Facility Particulars)."},{"type":"paragraph","text":"Without limiting the generality of sub-clause 27.3, each Obligor shall procure that all actions required to give full effect to Partial payments and set-off are completed within the timeframes and according to the procedures customary for a syndicated term facility of this nature, including delivery of certificates, opinions and evidence reasonably requested by the Agent acting on the instructions of the Majority Lenders."},{"type":"paragraph","text":"The Agent may, after consultation with the Borrower where practicable, issue guidance or process notes to the Lenders regarding operational matters arising under sub-clause 27.3, provided that such guidance does not amend the legal obligations of the Obligors without a formal amendment to the Finance Documents."},{"type":"paragraph","text":"In negotiating sub-clause 27.3, the Borrower and the Lenders typically consider counsel comments against the LMA recommended form, internal credit policy requirements, and any side letter or term sheet provisions agreed at mandate stage. Any deviation from the LMA baseline is recorded in the execution version of the Finance Documents."},{"type":"paragraph","text":"Operational application: where Partial payments and set-off applies to the Facility offered to Pacific Rim Holdings Ltd., the Agent will coordinate with the Borrower and the Security Agent to ensure timelines, document versions and evidence standards match those set out in Schedule 2 (Conditions Precedent) and Meridian Global Banking Corporation wholesale credit operations standards."},{"type":"paragraph","text":"27.4 Disruption to payment systems. The Borrower and each Finance Party acknowledge that the provisions of this sub-clause reflect standard LMA drafting for investment grade borrowers and are subject to facility-specific negotiation recorded in the term sheet and Schedule 1 (Facility Particulars)."},{"type":"paragraph","text":"Without limiting the generality of sub-clause 27.4, each Obligor shall procure that all actions required to give full effect to Disruption to payment systems are completed within the timeframes and according to the procedures customary for a syndicated term facility of this nature, including delivery of certificates, opinions and evidence reasonably requested by the Agent acting on the instructions of the Majority Lenders."},{"type":"paragraph","text":"The Agent may, after consultation with the Borrower where practicable, issue guidance or process notes to the Lenders regarding operational matters arising under sub-clause 27.4, provided that such guidance does not amend the legal obligations of the Obligors without a formal amendment to the Finance Documents."},{"type":"paragraph","text":"In negotiating sub-clause 27.4, the Borrower and the Lenders typically consider counsel comments against the LMA recommended form, internal credit policy requirements, and any side letter or term sheet provisions agreed at mandate stage. Any deviation from the LMA baseline is recorded in the execution version of the Finance Documents."},{"type":"paragraph","text":"Operational application: where Disruption to payment systems applies to the Facility offered to Pacific Rim Holdings Ltd., the Agent will coordinate with the Borrower and the Security Agent to ensure timelines, document versions and evidence standards match those set out in Schedule 2 (Conditions Precedent) and Meridian Global Banking Corporation wholesale credit operations standards."},{"type":"paragraph","text":"27.5 Relationship with Finance Documents and side letters. This supplemental sub-clause mirrors additional paragraphs commonly inserted in signed LMA-based facility offer letters and facility agreements to address operational and regulatory matters not captured in the short-form term sheet."},{"type":"paragraph","text":"Each Finance Party acknowledges that Relationship with Finance Documents and side letters may require further detail in the long-form facility agreement and security documents to be entered into on or before the first Utilisation Date."},{"type":"paragraph","text":"27.6 Amendments, waivers and consents under agency mechanics. This supplemental sub-clause mirrors additional paragraphs commonly inserted in signed LMA-based facility offer letters and facility agreements to address operational and regulatory matters not captured in the short-form term sheet."},{"type":"paragraph","text":"Each Finance Party acknowledges that Amendments, waivers and consents under agency mechanics may require further detail in the long-form facility agreement and security documents to be entered into on or before the first Utilisation Date."},{"type":"paragraph","text":"27.7 Conflicts with term sheet and order of precedence. This supplemental sub-clause mirrors additional paragraphs commonly inserted in signed LMA-based facility offer letters and facility agreements to address operational and regulatory matters not captured in the short-form term sheet."},{"type":"paragraph","text":"Each Finance Party acknowledges that Conflicts with term sheet and order of precedence may require further detail in the long-form facility agreement and security documents to be entered into on or before the first Utilisation Date."},{"type":"paragraph","text":"27.8 Regulatory change and compliance with PRA/FCA requirements. This supplemental sub-clause mirrors additional paragraphs commonly inserted in signed LMA-based facility offer letters and facility agreements to address operational and regulatory matters not captured in the short-form term sheet."},{"type":"paragraph","text":"Each Finance Party acknowledges that Regulatory change and compliance with PRA/FCA requirements may require further detail in the long-form facility agreement and security documents to be entered into on or before the first Utilisation Date."},{"type":"paragraph","text":"Clause 27A (Miscellaneous). The provisions of this Clause 27 shall survive any utilisation, prepayment or cancellation of the Facility and remain binding on the Obligors until all amounts outstanding under the Finance Documents have been irrevocably paid and discharged in full and the Commitments have been cancelled."}]}',
    change_description = 'Wave A refresh - LMA-style operative clauses',
    updated_at = (NOW() AT TIME ZONE 'UTC'),
    updated_by = '10000007'
FROM content_module cm
WHERE v.module_id = cm.id
  AND cm.module_code = 'MOD-FOL-SEC-27'
  AND cm.deleted_at IS NULL
  AND v.semantic_version = '1.0.0';

